<?php

declare(strict_types=1);

namespace App\Http\Controllers\Auth;

use App\Auth\UserRepository;
use Sahil\Auth\AuthManager;
use Sahil\Auth\PasswordResetManager;
use Sahil\Contracts\Foundation\ApplicationContract;
use Sahil\Contracts\View\ViewContract;
use Sahil\Http\Request;
use Sahil\Http\Response;
use Sahil\Validation\ValidationResult;
use Sahil\Validation\Validator;
use Throwable;

/**
 * Password reset form endpoints generated by `php sahil unda:auth`.
 *
 * The token is validated against the database, the account's password is
 * replaced with a fresh hash, every outstanding reset link is revoked, and
 * the user is signed in.
 */
final class ResetPasswordController
{
    public function __construct(
        private readonly ViewContract $views,
        private readonly ApplicationContract $application,
        private readonly AuthManager $auth,
        private readonly PasswordResetManager $reset,
        private readonly UserRepository $users,
    ) {
    }

    /**
     * @param array<string, string> $params route parameters; `token` comes from the reset link
     */
    public function showResetForm(Request $request, array $params = []): Response
    {
        return $this->page('auth.reset-password', [
            'token' => (string) ($params['token'] ?? ''),
        ]);
    }

    /**
     * @param array<string, string> $params
     */
    public function reset(Request $request, array $params = []): Response
    {
        $form = $request->form();
        $token = (string) ($params['token'] ?? $form['token'] ?? '');
        $email = $this->email($form);

        $result = $this->validator([
            'token' => 'required|string',
            'email' => 'required|email|length:3,190',
            ...$this->passwordRules($form),
        ], [
            'token.required' => 'This reset link is incomplete. Request a new one.',
            'email.required' => 'Enter the email address for your account.',
            'email.email' => 'Enter a valid email address, like you@example.com.',
            'email.length' => 'That email address is too long.',
            'password.required' => 'Choose a new password.',
            'password.length' => 'Use at least 8 characters for your new password.',
            'password_confirmation.required' => 'Repeat your new password.',
        ])->validate([...$form, 'token' => $token, 'email' => $email]);

        $data = [...$form, 'token' => $token];

        if ($result->fails()) {
            return $this->formPage('auth.reset-password', $result, $data);
        }

        $user = $this->reset->validateToken($token, $email);

        if ($user === null) {
            return $this->formPage('auth.reset-password', $result, $data, null, [
                'token' => 'This password reset link is invalid or has expired. Request a new one.',
            ]);
        }

        try {
            $this->users->updatePassword($user, $this->oldString($form, 'password'));
        } catch (Throwable) {
            return $this->formPage('auth.reset-password', $result, $data, null, [
                'token' => 'We could not save that password right now. Please try again.',
            ]);
        }

        // Single use: every outstanding link for this account stops working.
        $this->reset->deleteTokens($user);
        $this->auth->login($user);

        return Response::redirect('/dashboard', 303);
    }

    /**
     * @param array<string, string> $form
     *
     * @return array<string, string|array<int, string|\Closure>>
     */
    private function passwordRules(array $form): array
    {
        return [
            'password' => [
                'required',
                'string',
                'length:8,255',
                static function (string $path, mixed $value): ?string {
                    if (!is_string($value)
                        || preg_match('/[A-Za-z]/', $value) !== 1
                        || preg_match('/\d/', $value) !== 1) {
                        return 'Use at least 8 characters, including a letter and a number.';
                    }

                    return null;
                },
            ],
            'password_confirmation' => [
                'required',
                'string',
                static function (string $path, mixed $value) use ($form): ?string {
                    return is_string($value) && $value === ($form['password'] ?? null)
                        ? null
                        : 'The password confirmation does not match.';
                },
            ],
        ];
    }

    /**
     * @param array<string, string|array<int, string|\Closure>> $rules
     * @param array<string, string> $messages
     */
    private function validator(array $rules, array $messages): Validator
    {
        return new Validator($rules, $messages);
    }

    /**
     * @param array<string, string> $form
     * @param array<string, string> $errors
     */
    private function formPage(
        string $view,
        ?ValidationResult $result = null,
        array $form = [],
        ?string $status = null,
        array $errors = [],
    ): Response {
        $messages = [];

        foreach ($result?->errors() ?? [] as $field => $list) {
            $messages[$field] = $list[0] ?? '';
        }

        return $this->page($view, [
            'errors' => [...$messages, ...$errors],
            'old' => [
                'email' => $this->oldString($form, 'email'),
                'token' => $this->oldString($form, 'token'),
            ],
            'token' => $this->oldString($form, 'token'),
            'status' => $status,
        ]);
    }

    /**
     * @param array<string, mixed> $form
     */
    private function oldString(array $form, string $key): string
    {
        $value = $form[$key] ?? '';

        return is_string($value) ? $value : '';
    }

    /**
     * @param array<string, mixed> $form
     */
    private function email(array $form): string
    {
        return strtolower(trim($this->oldString($form, 'email')));
    }

    /**
     * @param array<string, mixed> $data
     */
    private function page(string $view, array $data = []): Response
    {
        return Response::html($this->views->render($view, [
            'app_name' => (string) $this->application->config()->get('app.name', 'SahilPHP'),
            'year' => gmdate('Y'),
            'csrf_token' => csrf_token(),
            ...$data,
        ]));
    }
}
